SELECT sku, product_name, pack_size, flow_type
FROM store.products
WHERE lower(product_name) LIKE '%atta%' AND pack_size = '5 kg';

SELECT sku, name, pack, flow
FROM store.products
WHERE lower(name) LIKE '%atta%' AND pack = '5 kg';

SELECT sku, name, pack
FROM store.products
WHERE sku = 'ATTA-WW-5KG';
